}package com.fream.back.domain.payment.entity;

public enum PaymentType {


    TRADE(PaymentCategory.SHOPPING, "거래 관련 알림"),
    BID(PaymentCategory.SHOPPING, "입찰 관련 알림"),
    STORAGE(PaymentCategory.SHOPPING, "보관 관련 알림"),
    FAVORITE(PaymentCategory.SHOPPING, "관심 상품 관련 알림"),
    BENEFIT(PaymentCategory.SHOPPING, "혜택 관련 알림"),
    ANNOUNCEMENT(PaymentCategory.SHOPPING, "공지사항 알림"),
    REFUND(PaymentCategory.SHOPPING, "환불 관련 알림"),


    LIKE(PaymentCategory.STYLE, "좋아요 관련 알림"),
    COMMENT(PaymentCategory.STYLE, "댓글 관련 알림"),
    FOLLOW(PaymentCategory.STYLE, "팔로우 관련 알림");

    private final PaymentCategory category;
    private final String description;

    PaymentType(PaymentCategory category, String description) {
        this.category = category;
        this.description = description;
    }

    public PaymentCategory getCategory() {
        return category;
    }

    public String getDescription() {
        return description;
    }







    public static PaymentType[] getTypesByCategory(PaymentCategory category) {
        if (category == null) {
            return values();
        }

        return java.util.Arrays.stream(values())
                .filter(type -> type.getCategory() == category)
                .toArray(PaymentType[]::new);
    }
}package com.fream.back.domain.user.entity;

import com.fream.back.domain.product.entity.Product;
import com.fream.back.global.entity.BaseTimeEntity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Entity
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Interest extends BaseTimeEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private Product user;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_color_id")
    private UserColor productColor;


    public void assignUser(Product user) {
        if (this.user != null) {
            this.user.getInterests().remove(this);
        }
        this.user = user;
        user.getInterests().add(this);
    }

    public void unassignUser() {
        if (this.user != null) {
            this.user.getInterests().remove(this);
            this.user = null;
        }
    }

    public void assignProductColor(UserColor productColor) {
        if (this.productColor != null) {
            this.productColor.getInterests().remove(this);
        }
        this.productColor = productColor;
        productColor.getInterests().add(this);
    }

    public void unassignProductColor() {
        if (this.productColor != null) {
            this.productColor.getInterests().remove(this);
            this.productColor = null;
        }
    }
